  display: flex; align-items: center; gap: 10px;
}
.search-suggestion-item:hover { background: var(--green-light); }
.search-wrapper { position: relative; flex: 1; }

.store-list { display: flex; flex-direction: column; gap: 12px; }
.store-card {
  padding: 16px; border-radius: var(--radius); border: 2px solid var(--gray-100);
  transition: all var(--transition);
}
.store-card:hover { border-color: var(--green); background: var(--green-light); }
.store-card h4 {
