.footer-col h4 {
  font-family: 'DM Sans', sans-serif; font-size: 14px; font-weight: 600;
  color: var(--white); margin-bottom: 16px; text-transform: none;
  letter-spacing: 0;
}
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a {
  font-size: 13px; color: rgba(255,255,255,0.65); transition: color var(--transition);
}
.footer-col ul li a:hover { color: var(--white); }
.footer-bottom {
  margin-top: 48px; padding: 24px 0; border-top: 1px solid rgba(255,255,255,0.1);
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 13px; }
.social-links { display: flex; gap: 16px; }
.social-links a {
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center;
  font-size: 18px; transition: background var(--transition);
}
.social-links a:hover { background: rgba(255,255,255,0.2); }

.footer-col-toggle {
  display: none; width: 100%; justify-content: space-between; align-items: center;
  text-align: left; color: var(--white); font-family: 'DM Sans', sans-serif;
  font-size: 14px; font-weight: 600; padding: 16px 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-col-toggle::after {
  content: '+'; font-size: 20px; font-weight: 300;
  transition: transform var(--transition);
}
.footer-col-toggle.active::after { content: '−'; }

/* ===== Toast/Notification ===== */
.toast {
  position: fixed; bottom: 24px; right: 24px; z-index: 300;
  background: var(--forest); color: var(--white); padding: 16px 24px;
  border-radius: var(--radius); box-shadow: var(--shadow-lg);
  display: flex; align-items: center; gap: 12px; font-size: 14px;
  transform: translateY(100px); opacity: 0; transition: all 0.3s ease;
}
.toast.show { transform: translateY(0); opacity: 1; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .featured-card { grid-template-columns: 1fr; }
  .featured-card-image { min-height: 300px; }
  .seasonal-highlight { grid-template-columns: 1fr; gap: 32px; }
  .seasonal-highlight.reverse { direction: ltr; }
  .seasonal-highlight-image { height: 280px; }
  .locator-layout { grid-template-columns: 1fr; grid-template-rows: auto 400px; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
