  .nav-right .btn-primary { padding: 8px 16px; font-size: 13px; }
  .mobile-menu-btn { display: flex; }
  .promo-grid { grid-template-columns: 1fr; }
  .steps { grid-template-columns: 1fr; }
  .tiers-grid { grid-template-columns: 1fr; }
  .partnerships { grid-template-columns: 1fr; }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col h4 { display: none; }
  .footer-col ul { display: none; padding: 0 0 16px 0; }
  .footer-col-toggle { display: flex; }
  .footer-col.open ul { display: block; }
  .redemption-tabs { gap: 6px; }
  .redemption-tab { padding: 10px 16px; font-size: 13px; }
  .carousel-header { flex-direction: column; align-items: flex-start; gap: 12px; }
  .featured-card-content { padding: 32px; }
  .business-gifting, .app-download, .nondairy-banner { padding: 32px; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .hero-content { padding: 60px 16px; }
  .section { padding: 48px 0; }
  .cookie-banner { padding: 16px; }
  .cookie-banner-actions { flex-direction: column; }
  .gift-card { flex: 0 0 160px; }
}

